"use strict";

// Real animated-GIF and static-image fixtures with known properties, produced by
// Pillow (an independent GIF encoder) and embedded as base64 so the repository
// stays text-only. Materialise them with writeFixtures(dir).
//
// - OVERSIZED_GIF: 2560x1440, 3 frames, delays [120,80,200] ms, loop 2.
// - SMALL_GIF:      320x180, 4 frames, delays [60,90,60,90] ms, loop 0, transparent.
// - STATIC_PNG:     640x360, single frame.

const OVERSIZED_GIF = "";
const SMALL_GIF = "";
const STATIC_PNG = "";

function writeFixtures(directory) {
	const fs = require("node:fs");
	const path = require("node:path");
	fs.mkdirSync(directory, { recursive: true });
	const write = (name, base64) => {
		const file = path.join(directory, name);
		fs.writeFileSync(file, Buffer.from(base64, "base64"));
		return file;
	};
	return {
		oversizedGif: write("fixture-oversized.gif", OVERSIZED_GIF),
		smallGif: write("fixture-small.gif", SMALL_GIF),
		staticPng: write("fixture-static.png", STATIC_PNG),
	};
}

module.exports = { OVERSIZED_GIF, SMALL_GIF, STATIC_PNG, writeFixtures };
